/// <reference path="../../index.d.ts" />
import type { PublicLitElement as LitElement } from "@arcgis/lumina";
import type { Scale } from "../types.js";

declare module "@arcgis/lumina" {
export interface DeclareCssProperties {
  /** Specifies the component's background color. */
  "--calcite-list-background-color": "*";
  /** Specifies the component's color. */
  "--calcite-list-color": "*";
}
}

/** @slot  - A slot for adding `calcite-list-item` and `calcite-list-item-group` elements. */
export abstract class ListItemGroup extends LitElement {
  /**
   * When `true`, interaction is prevented and the component is displayed with lower opacity.
   *
   * @default false
   */
  accessor disabled: boolean;
  /** Specifies the heading text for the nested `calcite-list-item` rows. */
  accessor heading: string | undefined;
  /**
   * Specifies the size of the component.
   *
   * @default "m"
   * @internal
   */
  accessor scale: Scale;
}